package vault

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// The fixture is generated by the website's scripts/vault-parity.ts and must
// never be hand-edited. It is the only proof that the TypeScript implementation
// produces a vault this package verifies byte for byte: the proof payload, the
// AAD layouts, the HKDF info strings, and the recovery key encoding all have to
// agree across Go, Python, and TypeScript, and only a fixture built by the
// other implementation proves it.
//
// Regenerate with:
//
//	cd ../agentsecrets-website && node --experimental-strip-types \
//	  scripts/vault-parity.ts create /tmp/browser-vault.json
//	cp /tmp/browser-vault.json pkg/vault/testdata/browser_vault.json
func TestBrowserBuiltVaultVerifiesAndUnlocks(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("testdata", "browser_vault.json"))
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	var fixture struct {
		UserID      string          `json:"user_id"`
		Password    string          `json:"password"`
		PrivateKey  string          `json:"private_key"`
		RecoveryKey string          `json:"recovery_key"`
		Vault       json.RawMessage `json:"vault"`
	}
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatalf("unmarshal fixture: %v", err)
	}

	var v Vault
	if err := json.Unmarshal(fixture.Vault, &v); err != nil {
		t.Fatalf("unmarshal vault: %v", err)
	}
	if err := v.Validate(); err != nil {
		t.Fatalf("browser vault failed structural validation: %v", err)
	}
	if err := v.Verify(fixture.UserID); err != nil {
		t.Fatalf("browser vault proof failed to verify: %v", err)
	}

	vk, err := v.UnlockWithPassword(fixture.UserID, fixture.Password)
	if err != nil {
		t.Fatalf("password unlock failed: %v", err)
	}
	priv, err := v.PrivateKey(fixture.UserID, vk)
	if err != nil {
		t.Fatalf("private key open failed: %v", err)
	}
	if got := b64(priv); got != fixture.PrivateKey {
		t.Fatal("unsealed private key does not match what the browser sealed")
	}

	rvk, err := v.UnlockWithRecoveryKey(fixture.UserID, fixture.RecoveryKey)
	if err != nil {
		t.Fatalf("recovery key unlock failed: %v", err)
	}
	if string(rvk) != string(vk) {
		t.Fatal("recovery key unwrapped a different vault key")
	}
}
